    """Every court starts with one price: its own price, counted as before."""
    Good = apps.get_model("goods", "Good")
    CourtPrice = apps.get_model("goods", "CourtPrice")
    for good in Good.objects.filter(kind="RENTAL", rental__isnull=False).select_related("rental"):
        per = good.rental.price_per
        CourtPrice.objects.create(
            good=good,
            name="Per person" if per == "PERSON" else "Whole court",
            price=good.price,
            per=per,
        )


